def re_arrange(arr, n):
    pos = []
    neg = []

    for i in range(n):
        if arr[i] >= 0:
            pos.append(arr[i])
        else:
            neg.append(arr[i])

    result = []
    p, q = 0, 0

    while p < len(pos) and q < len(neg):
        result.append(neg[q])
        result.append(pos[p])
        p += 1
        q += 1

    while p < len(pos):
        result.append(pos[p])
        p += 1

    while q < len(neg):
        result.append(neg[q])
        q += 1

    return result

def num_comm_div(a, b):
    divisors_a = []
    divisors_b = []

    for i in range(1, a + 1):
        if a % i == 0:
            divisors_a.append(i)

    for i in range(1, b + 1):
        if b % i == 0:
            divisors_b.append(i)

    common_divisors = set(divisors_a) & set(divisors_b)
    return max(common_divisors)

def permutation_coefficient(n, k):
    result = 1
    for i in range(k):
        result *= (n - i)
    return result
